1	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
2	import { RefreshCw, Search, X } from "lucide-react";
3	import { getProviders, type Api, type Model } from "@earendil-works/pi-ai/compat";
4	import { localModel, getModelName, getModelId, type LocalModel } from "../stores/local-model";
5	import { getSelectableModels, buildSavedModel } from "../lib/provider-models";
6	import { addRecentModel, getRecentModels } from "../keating/ui-settings";
7	import { loadModelPrefs } from "../keating/model-prefs";
8	import { css } from "../../styled-system/css";
9	
10	function makeBrowserModel(): Model<Api> {
11		return {
12			id: getModelId(),
13			name: getModelName(),
14			api: "browser" as Api,
15			provider: "browser",
16			baseUrl: "",
17			reasoning: false,
18			input: ["text"],
19			cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
20			contextWindow: 0,
21			maxTokens: 0,
22		};
23	}
24	
25	type SelectableModel = {
26		key: string;
27		model: Model<Api>;
28		group: "recent" | "browser" | "cloud" | "custom";
29	};
30	
31	function modelKey(model: Model<any>): string {
32		return `${model.provider}::${model.api}::${model.id}`;
33	}
34	
35	export interface ModelSelectorDialogProps {
36		open: boolean;
37		currentModel: Model<Api> | null;
38		onClose: () => void;
39		onSelect: (model: Model<Api>) => void;
40	}
41	
42	export function ModelSelectorDialog({ open, currentModel, onClose, onSelect }: ModelSelectorDialogProps) {
43		const [models, setModels] = useState<SelectableModel[]>([]);
44		const [loading, setLoading] = useState(true);
45		const [error, setError] = useState("");
46		const [search, setSearch] = useState("");
47		const [providerFilter, setProviderFilter] = useState("all");
48		const [selectedKey, setSelectedKey] = useState(currentModel ? modelKey(currentModel) : modelKey(makeBrowserModel()));
49		const [localState, setLocalState] = useState<LocalModel | null>(null);
50		const [webGpuAvailable, setWebGpuAvailable] = useState(false);
51		const inputRef = useRef<HTMLInputElement>(null);
52	
53		useEffect(() => {
54			if (!open) return;
55			setSearch("");
56			setProviderFilter("all");
57			setSelectedKey(currentModel ? modelKey(currentModel) : modelKey(makeBrowserModel()));
58			checkWebGpu().then(setWebGpuAvailable);
59			const unsub = localModel.subscribe(setLocalState);
60			loadModels();
61			// Focus search input after a short delay
62			window.setTimeout(() => inputRef.current?.focus(), 50);
63			return () => unsub();
64		}, [open, currentModel]);
65	
66		const checkWebGpu = async (): Promise<boolean> => {
67			if (!navigator.gpu) return false;
68			try {
69				return (await navigator.gpu.requestAdapter()) !== null;
70			} catch {
71				return false;
72			}
73		};
74	
75		const loadModels = async () => {
76			setLoading(true);
77			setError("");
78			try {
79				const modelPrefs = loadModelPrefs();
80				const hidden = new Set(modelPrefs.hiddenProviders);
81				const all = await getSelectableModels((provider) => !hidden.has(provider));
82	
83				// Append saved custom models
84				for (const saved of modelPrefs.customModels) {
85					all.push(buildSavedModel(saved));
86				}
87	
88				const knownProviders = new Set<string>(getProviders());
89				const selectable: SelectableModel[] = all.map((model) => ({
90					key: modelKey(model),
91					model,
92					group:
93						model.provider === "browser"
94							? "browser"
95							: knownProviders.has(model.provider)
96								? "cloud"
97								: "custom",
98				}));
99	
100				if (webGpuAvailable) {
101					selectable.unshift({ key: modelKey(makeBrowserModel()), model: makeBrowserModel(), group: "browser" });
102				}
103	
104				const deduped = new Map<string, SelectableModel>();
105				for (const m of selectable) deduped.set(m.key, m);
106	
107				setModels(Array.from(deduped.values()));
108			} catch (err) {
109				setError(err instanceof Error ? err.message : String(err));
110				setModels(webGpuAvailable ? [{ key: modelKey(makeBrowserModel()), model: makeBrowserModel(), group: "browser" }] : []);
111			} finally {
112				setLoading(false);
113			}
114		};
115	
116		const filtered = useMemo(() => {
117			const q = search.trim().toLowerCase();
118			const provider = providerFilter;
119			return models.filter(({ model }) => {
120				if (provider !== "all" && model.provider !== provider) return false;
121				if (!q) return true;
122				const haystack = `${model.name} ${model.id} ${model.provider}`.toLowerCase();
123				return haystack.includes(q);
124			});
125		}, [search, providerFilter, models]);
126	
127		const providerOptions = useMemo(
128			() =>
129				Array.from(new Set(models.map(({ model }) => model.provider))).sort((left, right) =>
130					left.localeCompare(right),
131				),
132			[models],
133		);
134	
135		const recentKeys = useMemo(
136			() => new Set(search.trim() === "" ? getRecentModels().map((m) => m.key) : []),
137			[search],
138		);
139	
140		const recentModels = filtered.filter((e) => recentKeys.has(e.key));
141		const browserModels = filtered.filter((e) => e.group === "browser" && !recentKeys.has(e.key));
142		const cloudModels = filtered.filter((e) => e.group === "cloud" && !recentKeys.has(e.key));
143		const customModels = filtered.filter((e) => e.group === "custom" && !recentKeys.has(e.key));
144	
145		const handleSelect = async () => {
146			const selected = models.find((e) => e.key === selectedKey)?.model;
147			if (!selected) return;
148			if (selected.provider === "browser" && !localState?.loaded) {
149				await localModel.load();
150				if (!localModel.getState().loaded) return;
151			}
152			addRecentModel(modelKey(selected));
153			onSelect(selected);
154			setSearch("");
155		};
156	
157		if (!open) return null;
158	
159		return (
160			<div
161				className={css({
162					position: "fixed",
163					inset: 0,
164					zIndex: 1000,
165					display: "flex",
166					alignItems: "center",
167					justifyContent: "center",
168					background: "rgba(0, 0, 0, 0.6)",
169					paddingInline: { base: "0.75rem", sm: "1rem" },
170					fontFamily: "monospace",
171				})}
172				onClick={onClose}
173			>
174				<div
175					role="dialog"
176					aria-modal="true"
177					className={css({
178						display: "flex",
179						width: "min(720px, 96vw)",
180						maxHeight: { base: "92vh", sm: "85vh" },
181						flexDirection: "column",
182						overflow: "hidden",
183						borderRadius: "0.5rem",
184						border: "2px solid var(--border)",
185						background: "var(--background)",
186					})}
187					onClick={(e) => e.stopPropagation()}
188				>
189					<div className={css({ flexShrink: 0, borderBottom: "1px solid var(--border)", padding: { base: "0.75rem", sm: "1rem" } })}>
190						<div>
191							<h2 className={css({ fontSize: { base: "0.875rem", sm: "1rem" }, fontWeight: 600, color: "var(--foreground)" })}>Select Model</h2>
192							<p className={css({ marginTop: "0.125rem", fontSize: { base: "0.6875rem", sm: "0.75rem" }, color: "var(--muted-foreground)" })}>Built-in providers and discovered custom-provider models.</p>
193						</div>
194						<div className={css({ marginTop: { base: "0.5rem", sm: "0.75rem" }, display: "grid", gap: "0.5rem", sm: { gridTemplateColumns: "minmax(0, 1fr) minmax(10rem, 14rem) auto" } })}>
195							<label className={css({ minWidth: 0 })}>
196								<span className={css({ position: "absolute", width: "1px", height: "1px", padding: 0, margin: "-1px", overflow: "hidden", clip: "rect(0, 0, 0, 0)", whiteSpace: "nowrap", borderWidth: 0 })}>Search models</span>
197								<input
198									ref={inputRef}
199									type="text"
200									placeholder="Search models"
201									className={css({ width: "100%", borderRadius: "0.375rem", border: "2px solid var(--border)", background: "var(--background)", padding: "0.375rem 0.625rem", fontSize: { base: "0.75rem", sm: "0.875rem" } })}
202									value={search}
203									onChange={(e) => setSearch(e.target.value)}
204								/>
205							</label>
206							<label className={css({ minWidth: 0 })}>
207								<span className={css({ position: "absolute", width: "1px", height: "1px", padding: 0, margin: "-1px", overflow: "hidden", clip: "rect(0, 0, 0, 0)", whiteSpace: "nowrap", borderWidth: 0 })}>Filter by provider</span>
208								<select
209									className={css({ width: "100%", borderRadius: "0.375rem", border: "2px solid var(--border)", background: "var(--background)", padding: "0.375rem 0.625rem", fontSize: { base: "0.75rem", sm: "0.875rem" } })}
210									value={providerFilter}
211									onChange={(e) => setProviderFilter(e.target.value)}
212								>
213									<option value="all">All providers</option>
214									{providerOptions.map((provider) => (
215										<option key={provider} value={provider}>
216											{provider}
217										</option>
218									))}
219								</select>
220							</label>
221							<button
222								onClick={() => {
223									setLoading(true);
224									loadModels();
225								}}
226								className={css({
227									display: "inline-flex",
228									alignItems: "center",
229									justifyContent: "center",
230									gap: "0.25rem",
231									borderRadius: "0.375rem",
232									border: "2px solid var(--border)",
233									padding: "0.375rem 0.625rem",
234									fontSize: { base: "0.75rem", sm: "0.875rem" },
235									transition: "color 150ms, background-color 150ms",
236									_hover: { background: "var(--ink)", color: "var(--paper)" },
237								})}
238							>
239								<RefreshCw size={13} />
240								Refresh
241								</button>
242						</div>
243					</div>
244	
245					<div className={css({ margin: "0.25rem", flex: 1, overflowY: "auto", border: "1px solid var(--border)", background: "color-mix(in srgb, var(--muted) 20%, transparent)" })}>
246						{loading ? (
247							<div className={css({ padding: { base: "0.75rem", sm: "1rem" }, textAlign: "center", fontSize: "0.875rem", color: "var(--muted-foreground)" })}>Loading models…</div>
248							) : error ? (
249							<div className={css({ padding: { base: "0.75rem", sm: "1rem" }, textAlign: "center", fontSize: "0.875rem", color: "var(--destructive)" })}>{error}</div>
250						) : filtered.length === 0 ? (
251							<div className={css({ padding: { base: "0.75rem", sm: "1rem" }, textAlign: "center", fontSize: "0.875rem", color: "var(--muted-foreground)" })}>No models matched the current search.</div>
252						) : (
253							<>
254								{renderGroup("Recent", recentModels, selectedKey, setSelectedKey, localState, webGpuAvailable)}
255								{renderGroup("Browser", browserModels, selectedKey, setSelectedKey, localState, webGpuAvailable)}
256								{renderGroup("Cloud", cloudModels, selectedKey, setSelectedKey, localState, webGpuAvailable)}
257								{renderGroup("Custom Providers", customModels, selectedKey, setSelectedKey, localState, webGpuAvailable)}
258							</>
259						)}
260					</div>
261	
262					<div className={css({ display: "flex", flexShrink: 0, justifyContent: "flex-end", gap: "0.5rem", borderTop: "1px solid var(--border)", padding: { base: "0.75rem", sm: "1rem" } })}>
263						<button
264							onClick={onClose}
265							className={css({
266								borderRadius: "0.375rem",
267								border: "2px solid var(--border)",
268								paddingInline: { base: "0.75rem", sm: "1rem" },
269								paddingBlock: { base: "0.375rem", sm: "0.5rem" },
270								fontSize: { base: "0.75rem", sm: "0.875rem" },
271								transition: "color 150ms, background-color 150ms",
272								_hover: { background: "var(--ink)", color: "var(--paper)" },
273							})}
274						>
275							Cancel
276						</button>
277						<button
278							onClick={handleSelect}
279							className={css({
280								borderRadius: "0.375rem",
281								border: "2px solid var(--primary)",
282								background: "var(--primary)",
283								paddingInline: { base: "0.75rem", sm: "1rem" },
284								paddingBlock: { base: "0.375rem", sm: "0.5rem" },
285								fontSize: { base: "0.75rem", sm: "0.875rem" },
286								color: "var(--primary-foreground)",
287								transition: "color 150ms, background-color 150ms",
288								_hover: { background: "color-mix(in srgb, var(--primary) 90%, black)" },
289							})}
290						>
291							Use Selected Model
292						</button>
293					</div>
294				</div>
295			</div>
296		);
297	}
298	
299	function renderGroup(
300		title: string,
301		models: SelectableModel[],
302		selectedKey: string,
303		onSelect: (key: string) => void,
304		localState: LocalModel | null,
305		webGpuAvailable: boolean,
306	) {
307		if (models.length === 0) return null;
308		return (
309			<div>
310				<div className={css({
311					position: "sticky",
312					top: 0,
313					zIndex: 10,
314					borderBlock: "1px solid var(--border)",
315					background: "color-mix(in srgb, var(--muted) 80%, transparent)",
316					paddingInline: { base: "0.75rem", sm: "1rem" },
317					paddingBlock: "0.25rem",
318					fontSize: "0.625rem",
319					fontWeight: 600,
320					letterSpacing: "0.05em",
321					textTransform: "uppercase",
322					color: "var(--muted-foreground)",
323					backdropFilter: "blur(8px)",
324				})}>
325					{title}
326				</div>
327				{models.map((entry) => (
328					<ModelOption
329						key={entry.key}
330						entry={entry}
331						isSelected={selectedKey === entry.key}
332						onClick={() => onSelect(entry.key)}
333						localState={localState}
334						webGpuAvailable={webGpuAvailable}
335					/>
336				))}
337			</div>
338		);
339	}
340	
341	function ModelOption({
342		entry,
343		isSelected,
344		onClick,
345		localState,
346		webGpuAvailable,
347	}: {
348		entry: SelectableModel;
349		isSelected: boolean;
350		onClick: () => void;
351		localState: LocalModel | null;
352		webGpuAvailable: boolean;
353	}) {
354		const { model, key } = entry;
355		const isBrowser = model.provider === "browser";
356		const disabled = isBrowser && !webGpuAvailable;
357	
358		const badges = [
359			isBrowser ? "WebGPU" : "",
360			entry.group === "cloud" ? "Cloud" : "",
361			entry.group === "custom" ? "Custom" : "",
362			model.input.includes("image") ? "Vision" : "",
363			model.reasoning ? "Thinking" : "",
364		].filter(Boolean);
365	
366		const status = (): string => {
367			if (model.provider !== "browser") return "";
368			if (!webGpuAvailable) return "WebGPU not available";
369			if (localState?.loading) return `Loading browser model... ${localState.loadingProgress}%`;
370			if (localState?.loaded) return "Model ready";
371			if (localState?.error) return localState.error;
372			return "Loads on demand when selected";
373		};
374	
375		return (
376			<div
377				className={css({
378					display: "flex",
379					alignItems: "flex-start",
380					gap: { base: "0.625rem", sm: "0.75rem" },
381					borderBottom: "1px solid var(--border)",
382					background: isSelected ? "color-mix(in srgb, var(--primary) 5%, transparent)" : undefined,
383					paddingInline: { base: "0.75rem", sm: "1rem" },
384					paddingBlock: { base: "0.5rem", sm: "0.75rem" },
385					cursor: disabled ? "not-allowed" : "pointer",
386					opacity: disabled ? 0.45 : undefined,
387					transition: "color 150ms, background-color 150ms",
388					_hover: disabled ? undefined : { background: "color-mix(in srgb, var(--accent) 30%, transparent)" },
389				})}
390				onClick={() => {
391					if (!disabled) onClick();
392				}}
393			>
394				<input
395					type="radio"
396					name="model"
397					checked={isSelected}
398					readOnly
399					disabled={disabled}
400					className={css({ marginTop: { base: "0.125rem", sm: "0.25rem" }, flexShrink: 0 })}
401				/>
402				<div className={css({ minWidth: 0, flex: 1 })}>
403					<div className={css({ fontSize: "0.875rem", fontWeight: 700, lineHeight: 1.25 })}>{model.name}</div>
404					<div className={css({ marginTop: "0.125rem", fontSize: { base: "0.6875rem", sm: "0.75rem" }, color: "var(--muted-foreground)" })}>
405						{isBrowser ? "Runs in this browser" : `Provider: ${model.provider}`}
406					</div>
407					<div className={css({ fontSize: { base: "0.6875rem", sm: "0.75rem" }, color: "var(--muted-foreground)" })}>{model.id}</div>
408					{badges.length > 0 && (
409						<div className={css({ marginTop: "0.375rem", display: "flex", flexWrap: "wrap", gap: "0.25rem" })}>
410							{badges.map((b) => (
411								<span key={b} className={css({ display: "inline-flex", borderRadius: "9999px", background: "var(--muted)", padding: "0.125rem 0.5rem", fontSize: "0.625rem", fontWeight: 600, color: "var(--muted-foreground)" })}>
412									{b}
413								</span>
414								))}
415							</div>
416						)}
417						{status() && (
418							<div className={css({
419								marginTop: "0.25rem",
420								fontSize: "0.75rem",
421								color: status().includes("error") || status().includes("not available")
422									? "var(--destructive)"
423									: status().includes("ready")
424										? "var(--primary)"
425										: status().includes("Loading")
426											? "#2563eb"
427											: "var(--muted-foreground)",
428							})}>
429								{status()}
430								{localState?.loading && (
431									<div className={css({ marginTop: "0.25rem", height: "0.25rem", width: "100%", overflow: "hidden", borderRadius: "9999px", background: "color-mix(in srgb, var(--muted-foreground) 20%, transparent)" })}>
432										<div className={css({ height: "100%", borderRadius: "9999px", background: "#2563eb", transition: "all 150ms" })} style={{ width: `${localState.loadingProgress}%` }} />
433									</div>
434								)}
435							</div>
436						)}
437					</div>
438				</div>
439			);
440		}
