1	import { getModels, getProviders, type Api, type Model } from "@earendil-works/pi-ai/compat";
2	import { getAppStorage, type CustomProvider } from "@earendil-works/pi-web-ui";
3	import { proxiedProviderRequestUrl } from "./provider-proxy";
4	import { DIO_DEFAULT_MODEL, DIO_PROVIDER_ID } from "../dio-provider";
5	import { getOAuthAccessToken, providerToOAuthId } from "../keating/oauth";
6	import { withApiRetry } from "../keating/api-retry";
7	
8	export type KeatingCustomProviderType =
9		| "ollama"
10		| "llama.cpp"
11		| "vllm"
12		| "lmstudio"
13		| "gateway"
14		| "openai-completions"
15		| "openai-responses"
16		| "anthropic-messages"
17		| "synthetic";
18	
19	export type KeatingGatewayKind = "bifrost" | "plexus" | "litellm" | "generic";
20	
21	export type KeatingCustomProvider = Omit<CustomProvider, "type"> & {
22		type: KeatingCustomProviderType;
23		gatewayKind?: KeatingGatewayKind;
24	};
25	
26	const AUTO_DISCOVERY_TYPES = new Set<KeatingCustomProviderType>(["ollama", "llama.cpp", "vllm", "lmstudio"]);
27	const OPENAI_COMPATIBLE_TYPES = new Set<KeatingCustomProviderType>([
28		"gateway",
29		"openai-completions",
30		"openai-responses",
31		"synthetic",
32	]);
33	
34	function trimTrailingSlash(value: string): string {
35		return value.replace(/\/+$/, "");
36	}
37	
38	function modelCost() {
39		return {
40			input: 0,
41			output: 0,
42			cacheRead: 0,
43			cacheWrite: 0,
44		};
45	}
46	
47	function toContextWindow(value: unknown, fallback = 0): number {
48		if (typeof value === "number" && Number.isFinite(value)) return value;
49		if (typeof value === "string") {
50			const parsed = Number.parseInt(value, 10);
51			if (Number.isFinite(parsed)) return parsed;
52		}
53		return fallback;
54	}
55	
56	function inferInputModes(model: any): Array<"text" | "image"> {
57		const supported = new Set<string>();
58	
59		if (Array.isArray(model?.input)) {
60			for (const entry of model.input) {
61				if (entry === "image" || entry === "text") supported.add(entry);
62			}
63		}
64	
65		if (Array.isArray(model?.input_modalities)) {
66			for (const entry of model.input_modalities) {
67				if (entry === "image" || entry === "text") supported.add(entry);
68			}
69		}
70	
71		if (Array.isArray(model?.modalities)) {
72			for (const entry of model.modalities) {
73				if (entry === "image" || entry === "text") supported.add(entry);
74			}
75		}
76	
77		if (model?.vision === true) supported.add("image");
78		if (supported.size === 0) supported.add("text");
79	
80		return Array.from(supported) as Array<"text" | "image">;
81	}
82	
83	function inferReasoning(model: any): boolean {
84		if (typeof model?.reasoning === "boolean") return model.reasoning;
85		if (typeof model?.supports_reasoning === "boolean") return model.supports_reasoning;
86		if (Array.isArray(model?.capabilities)) return model.capabilities.includes("thinking");
87		const name = String(model?.id ?? model?.name ?? "").toLowerCase();
88		return name.includes("thinking") || name.includes("reasoning");
89	}
90	
91	function manualProviderApi(type: KeatingCustomProviderType): Api {
92		switch (type) {
93			case "openai-responses":
94				return "openai-responses" as Api;
95			case "anthropic-messages":
96				return "anthropic-messages" as Api;
97			case "synthetic":
98			case "openai-completions":
99			default:
100				return "openai-completions" as Api;
101		}
102	}
103	
104	function openAiCompatibleBaseUrls(provider: KeatingCustomProvider): string[] {
105		const baseUrl = trimTrailingSlash(provider.baseUrl);
106		if (baseUrl.endsWith("/v1")) return [baseUrl];
107	
108		if (provider.type === "gateway" && provider.gatewayKind === "bifrost") {
109			return [`${baseUrl}/v1`, `${baseUrl}/openai/v1`, baseUrl];
110		}
111	
112		if (provider.type === "gateway") {
113			return [`${baseUrl}/v1`, baseUrl];
114		}
115	
116		return [baseUrl, `${baseUrl}/v1`];
117	}
118	
119	async function fetchJson(url: string, apiKey?: string, options: { method?: "GET" | "POST"; body?: unknown } = {}): Promise<any> {
120		const proxied = proxiedProviderRequestUrl(url);
121		const headers: Record<string, string> = {
122			"x-target-url": proxied.targetBaseUrl,
123		};
124	
125		if (options.body !== undefined) headers["Content-Type"] = "application/json";
126		if (apiKey) {
127			headers.Authorization = `Bearer ${apiKey}`;
128		}
129	
130		const response = await withApiRetry(async () => {
131			const result = await fetch(proxied.url, {
132				method: options.method ?? "GET",
133				headers,
134				body: options.body === undefined ? undefined : JSON.stringify(options.body),
135			});
136			if (!result.ok) {
137				const retryAfter = result.headers.get("retry-after");
138				throw new Error(`HTTP ${result.status}: ${result.statusText}${retryAfter ? ` retry-after: ${retryAfter}` : ""}`);
139			}
140			return result;
141		});
142	
143		const text = await response.text();
144		try {
145			return JSON.parse(text);
146		} catch {
147			const snippet = text.trim().slice(0, 120).replace(/\s+/g, " ");
148			throw new Error(
149				`Expected JSON from ${url} but got ${snippet ? `a non-JSON response ("${snippet}…")` : "an empty response"}. Check the base URL.`,
150			);
151		}
152	}
153	
154	async function discoverOpenAiCompatibleModels(
155		provider: KeatingCustomProvider,
156	): Promise<{ apiBaseUrl: string; models: Model<Api>[] }> {
157		const candidateBaseUrls = openAiCompatibleBaseUrls(provider);
158	
159		let lastError: unknown;
160		let emptyResult: { apiBaseUrl: string; models: Model<Api>[] } | undefined;
161		for (const apiBaseUrl of candidateBaseUrls) {
162			try {
163				const payload = await fetchJson(`${apiBaseUrl}/models`, provider.apiKey);
164				const records = Array.isArray(payload?.data) ? payload.data : Array.isArray(payload) ? payload : [];
165					const models = records
166						.map((record: any): Model<Api> | null => {
167						const id = String(record?.id ?? record?.name ?? "").trim();
168						if (!id) return null;
169	
170						const contextWindow = toContextWindow(
171							record?.context_window ?? record?.context_length ?? record?.max_context_length ?? record?.max_model_len,
172						);
173						const maxTokens = toContextWindow(record?.max_tokens ?? record?.max_output_tokens, contextWindow || 4096);
174	
175						return {
176							id,
177							name: String(record?.display_name ?? record?.name ?? id),
178							api: manualProviderApi(provider.type),
179							provider: provider.name,
180							baseUrl: apiBaseUrl,
181							reasoning: inferReasoning(record),
182							input: inferInputModes(record),
183							cost: modelCost(),
184							contextWindow,
185							maxTokens,
186						};
187						})
188						.filter((model: Model<Api> | null): model is Model<Api> => model !== null);
189	
190				if (models.length > 0) return { apiBaseUrl, models };
191				emptyResult ??= { apiBaseUrl, models };
192			} catch (error) {
193				lastError = error;
194			}
195		}
196	
197		if (emptyResult) return emptyResult;
198		throw lastError instanceof Error ? lastError : new Error(`Failed to discover models for ${provider.name}`);
199	}
200	
201	async function discoverOllamaModels(baseUrl: string): Promise<Model<Api>[]> {
202		const trimmedBaseUrl = trimTrailingSlash(baseUrl);
203		const payload = await fetchJson(`${trimmedBaseUrl}/api/tags`);
204		const models = Array.isArray(payload?.models) ? payload.models : [];
205	
206		const discovered = await Promise.all(
207			models.map(async (model: any): Promise<Model<Api> | null> => {
208				const details = await fetchJson(`${trimmedBaseUrl}/api/show`, undefined, {
209					method: "POST",
210					body: { model: model.name },
211				});
212				const capabilities: string[] = (details as any).capabilities || [];
213				if (!capabilities.includes("tools")) return null;
214	
215				const modelInfo: any = details.model_info || {};
216				const architecture = modelInfo["general.architecture"] || "";
217				const contextWindow = toContextWindow(modelInfo[`${architecture}.context_length`], 8192);
218	
219				return {
220					id: model.name,
221					name: model.name,
222					api: "openai-completions" as Api,
223					provider: "",
224					baseUrl: `${trimTrailingSlash(baseUrl)}/v1`,
225					reasoning: capabilities.includes("thinking"),
226					input: ["text"],
227					cost: modelCost(),
228					contextWindow,
229					maxTokens: contextWindow,
230				};
231			}),
232		);
233	
234		return discovered.filter((model): model is Model<Api> => model !== null);
235	}
236	
237	async function discoverLlamaCppModels(baseUrl: string, apiKey?: string): Promise<Model<Api>[]> {
238		const payload = await fetchJson(`${trimTrailingSlash(baseUrl)}/v1/models`, apiKey);
239		const records = Array.isArray(payload?.data) ? payload.data : [];
240	
241		return records.map((model: any) => {
242			const contextWindow = toContextWindow(model?.context_length, 8192);
243			return {
244				id: String(model.id),
245				name: String(model.id),
246				api: "openai-completions" as Api,
247				provider: "",
248				baseUrl: `${trimTrailingSlash(baseUrl)}/v1`,
249				reasoning: false,
250				input: ["text"],
251				cost: modelCost(),
252				contextWindow,
253				maxTokens: toContextWindow(model?.max_tokens, 4096),
254			};
255		});
256	}
257	
