2		label: "Learn" | "Plan" | "Map" | "Assess" | "Create";
3		text: string;
4		domain: string;
5	}
6	
7	export const STARTER_PROMPTS: StarterPrompt[] = [
8		{ label: "Learn", text: "How do vaccines train the immune system?", domain: "medicine" },
9		{ label: "Learn", text: "How does jazz improvisation work?", domain: "arts" },
10		{ label: "Learn", text: "Why do cities form where they do?", domain: "geography" },
11		{ label: "Learn", text: "Explain quantum entanglement simply", domain: "physics" },
