18		{ label: "Map", text: "Map the arguments about free will", domain: "philosophy" },
19		{ label: "Map", text: "How does a bill become law?", domain: "civics" },
20		{ label: "Assess", text: "Quiz me on the Krebs cycle", domain: "biology" },
21		{ label: "Assess", text: "Test my async/await knowledge", domain: "computing" },
22		{ label: "Assess", text: "Help me practice reading a nutrition label", domain: "life-skills" },
23		{ label: "Assess", text: "Give me a close-reading challenge for a poem", domain: "literature" },
24		{ label: "Create", text: "Animate how DNS works", domain: "computing" },
25		{ label: "Create", text: "Flashcards for Japanese particles", domain: "languages" },
26		{ label: "Create", text: "Build a timeline of the Silk Roads", domain: "history" },
27		{ label: "Create", text: "Show how climate feedback loops interact", domain: "earth-science" },
28	];
29	
30	function shuffled<T>(items: readonly T[], random: () => number): T[] {
31		const result = [...items];
32		for (let index = result.length - 1; index > 0; index -= 1) {
33			const swapIndex = Math.floor(random() * (index + 1));
34			[result[index], result[swapIndex]] = [result[swapIndex]!, result[index]!];
35		}
36		return result;
37	}
38	
39	/** Choose across domains before showing a second prompt from the same domain. */
40	export function pickDiverseStarterPrompts(
41		pool: readonly StarterPrompt[],
42		count: number,
43		random: () => number = Math.random,
44	): StarterPrompt[] {
45		if (count <= 0 || pool.length === 0) return [];
46		const byDomain = new Map<string, StarterPrompt[]>();
47		for (const prompt of shuffled(pool, random)) {
48			const entries = byDomain.get(prompt.domain) ?? [];
49			entries.push(prompt);
50			byDomain.set(prompt.domain, entries);
51		}
52		const selected: StarterPrompt[] = [];
53		let domains = shuffled([...byDomain.keys()], random);
54		while (selected.length < Math.min(count, pool.length) && domains.length > 0) {
55			const nextDomains: string[] = [];
56			for (const domain of domains) {
57				const prompt = byDomain.get(domain)?.shift();
58				if (prompt) selected.push(prompt);
59				if ((byDomain.get(domain)?.length ?? 0) > 0) nextDomains.push(domain);
